epon <input name="phone" required></label><label>WhatsApp <input name="whatsapp"></label><label>Tempat lahir <input name="birth_place" required></label><label>Tanggal lahir <input type="date" name="birth_date" required></label><label>Jenis kelamin <select name="gender" required><option value="">Pilih</option><option value="male">Laki-laki</option><option value="female">Perempuan</option></select></label><label>Agama <input name="religion" value="Islam"></label><label>Status perkawinan <select name="marital_status"><option value="">Pilih</option><option>Belum Kawin</option><option>Kawin</option><option>Cerai Hidup</option><option>Cerai Mati</option></select></label><label>Alamat <textarea name="address" required></textarea></label><label>Provinsi <input name="province" required></label><label>Kabupaten/Kota <input name="city" required></label><label>Kecamatan <input name="district" required></label><label>Desa/Kelurahan <input name="village" required></label><label>Kode pos <input name="postal_code"></label><h2>Data Pendidikan</h2><label>Asal SMA/SMK/MA <input name="previous_school" required></label><label>Jurusan <input name="school_major"></label><label>Tahun lulus <input type="number" name="graduation_year" required></label><label>Nomor ijazah <input name="diploma_number"></label><h2>Data Orang Tua/Wali</h2><label>Nama ayah <input name="father_name" required></label><label>Pekerjaan ayah <input name="father_occupation"></label><label>Telepon ayah <input name="father_phone"></label><label>Nama ibu <input name="mother_name" required></label><label>Pekerjaan ibu <input name="mother_occupation"></label><label>Telepon ibu <input name="mother_phone"></label><label>Nama wali <input name="guardian_name"></label><label>Telepon wali <input name="guardian_phone"></label><h2>Akademik</h2><label>Program studi <select name="study_program_id" required><?php foreach($pmbPrograms as $program): ?><option value="<?=$program['id']?>"><?=htmlspecialchars($program['name'],ENT_QUOTES,'U